import React, { useRef } from "react";
import Webcam from "react-webcam";

function CameraScanner({ onCapture }) {

    const webcamRef = useRef(null);

    const capture = () => {

        if (!webcamRef.current) {
            console.log("Webcam not ready");
            return;
        }

        const imageSrc = webcamRef.current.getScreenshot();

        console.log("Captured:", imageSrc);

        if (imageSrc) {
            onCapture(imageSrc);
        } else {
            console.log("Image capture failed");
        }
    };

    return (
        <div>

            <Webcam
                ref={webcamRef}
                screenshotFormat="image/jpeg"
                width={500}
                height={400}
            />

            <button onClick={capture}color="blue">
                Scan Ingredients
            </button>

        </div>
    );
}

export default CameraScanner;
